declare(strict_types=1);
ob_start();
set_error_handler(static function(int $severity,string $message,string $file,int $line): never { throw new ErrorException($message,0,$severity,$file,$line); });
require dirname(__DIR__).'/src/bootstrap.php';

final class FakeHttp extends Http {
    public array $calls=[];
    public function __construct(public array $steps=[]) {}
    public function request(string $method,string $url,array $headers=[],?string $body=null): array {
        $this->calls[]=[$method,$url,$body];
        $next=array_shift($this->steps); if (!$next) throw new RuntimeException('Unexpected HTTP: '.$method.' '.$url);
        if ($next instanceof Throwable) throw $next;
        if (is_callable($next)) return $next($method,$url,$headers,$body);
        return ['status'=>$next['status']??200,'headers'=>$next['headers']??[],'json'=>$next['json']??[]];
    }
}
function check(bool $condition,string $message): void { if (!$condition) throw new RuntimeException($message); }
function rejects(callable $fn,string $contains): void { try { $fn(); } catch (UserError $e) { check(str_contains($e->getMessage(),$contains),'Unexpected error: '.$e->getMessage()); return; } throw new RuntimeException('Expected rejection: '.$contains); }
$root=sys_get_temp_dir().'/publicera-test-'.bin2hex(random_bytes(5)); mkdir($root.'/storage/uploads',0700,true);
$dsn=getenv('PUBLICERA_TEST_DSN')?:'sqlite:'.$root.'/storage/tests.sqlite';
if (!str_starts_with($dsn,'sqlite:')&&!preg_match('/dbname=publicera_test_[a-z0-9]+(?:;|$)/',$dsn)) throw new RuntimeException('MySQL tests require a dedicated database named publicera_test_<suffix>.');
$app=new App($root,['url'=>'https://publicera.example','timezone'=>'Europe/Stockholm','key'=>base64_encode(random_bytes(32)),'database'=>['dsn'=>$dsn,'user'=>getenv('PUBLICERA_TEST_USER')?:null,'password'=>getenv('PUBLICERA_TEST_PASSWORD')?:null],'upload_limit_mb'=>100,'google'=>['client_id'=>'test','client_secret'=>'test'],'meta'=>['version'=>'v27.0']],false);
$app->migrate(); $app->migrate(); $app->session();
$passed=0;
function test(string $name,callable $fn): void { global $passed; $fn(); ++$passed; echo 'PASS '.$name.PHP_EOL; }
function channel(string $network,array $credentials): int { global $app; $app->query('INSERT INTO channels(network,external_id,name,credentials,connected_at) VALUES(?,?,?,?,?)',[$network,'channel-'.bin2hex(random_bytes(4)),$network,$app->seal($credentials),$app->now()]); return (int)$app->db->lastInsertId(); }
function scheduled(int $channel,array $media=[]): int { global $app; $id=$app->savePost(['title'=>'Testinlägg','caption'=>'Hej från testet','channel_ids'=>[$channel],'media_ids'=>$media,'status'=>'scheduled','scheduled_at'=>(new DateTimeImmutable('+1 hour',new DateTimeZone('Europe/Stockholm')))->format('Y-m-d\TH:i'),'timezone'=>'Europe/Stockholm','visibility'=>'private','made_for_kids'=>'no']); $app->query('UPDATE posts SET scheduled_at=? WHERE id=?',[gmdate('Y-m-d H:i:s',time()-60),$id]); $app->query('UPDATE publications SET next_at=? WHERE post_id=?',[$app->now(),$id]); return $id; }
function publication(int $post): array { global $app; return $app->one('SELECT * FROM publications WHERE post_id=?',[$post]); }

test('encrypted credentials round-trip and reject tampering',function()use($app){$encrypted=$app->seal(['access_token'=>'private-token']);check(!str_contains($encrypted,'private-token'),'Token leaked');check($app->unseal($encrypted)['access_token']==='private-token','Round trip');$raw=base64_decode($encrypted);$raw[30]=chr(ord($raw[30])^1);try{$app->unseal(base64_encode($raw));}catch(RuntimeException){return;}throw new RuntimeException('Tampered token accepted');});
test('login requires valid password and regenerates authenticated session',function()use($app){$app->query('INSERT INTO users(email,name,password_hash,created_at) VALUES(?,?,?,?)',['admin@example.se','Test',password_hash('correct-password',PASSWORD_DEFAULT),$app->now()]);rejects(fn()=>$app->login('admin@example.se','wrong'),'stämmer inte');$before=session_id();$app->login('admin@example.se','correct-password');check($app->user()['email']==='admin@example.se','No authenticated user');check(session_id()!==$before,'Session was not regenerated');});
test('CSRF rejects missing or stale request token',function()use($app){rejects(fn()=>$app->csrf(),'Sessionen');$_SERVER['HTTP_X_CSRF_TOKEN']=$_SESSION['csrf'];$app->csrf();});
test('expired worker budget stops before making any network request',function(){$http=new Http();$http->deadline(microtime(true)-1);try{$http->request('POST','https://graph.facebook.com/v27.0/test');}catch(WorkerBudgetExpired){return;}throw new RuntimeException('Expired worker dispatched network work');});
$fb=channel('facebook',['access_token'=>'fake-page-token']);
test('draft creation preserves UTF-8 and optimistic version conflicts are atomic',function()use($app){$caption=str_repeat('å🧡',18000);$id=$app->savePost(['title'=>'Utkast','caption'=>$caption,'status'=>'draft']);check($app->one('SELECT caption FROM posts WHERE id=?',[$id])['caption']===$caption,'UTF-8 truncated');rejects(fn()=>$app->savePost(['id'=>$id,'version'=>99,'title'=>'Bad','status'=>'draft']),'annan vy');check($app->one('SELECT version FROM posts WHERE id=?',[$id])['version']==1,'Conflict changed version');});
test('invalid and ambiguous DST times and missing Instagram media are rejected',function()use($app){rejects(fn()=>$app->savePost(['title'=>'DST','scheduled_at'=>'2027-03-28T02:30','timezone'=>'Europe/Stockholm']),'tiden är ogiltig');rejects(fn()=>$app->savePost(['title'=>'DST','scheduled_at'=>'2027-10-31T02:30','timezone'=>'Europe/Stockholm']),'två gånger');rejects(fn()=>$app->validatePublication('instagram','text',[]),'Instagram behöver');});
test('Facebook text publishes once and repeated cron does not duplicate',function()use($app,$fb){$id=scheduled($fb);$http=new FakeHttp([['json'=>['id'=>'123_456']]]);(new Publisher($app,$http))->run();check(publication($id)['status']==='published','Not published');(new Publisher($app,$http))->run();check(count($http->calls)===1,'Duplicate API call');});
test('transport uncertainty is preserved and never automatically retried',function()use($app,$fb){$id=scheduled($fb);$http=new FakeHttp([new RemoteFailure('timeout',true)]);(new Publisher($app,$http))->run();check(publication($id)['status']==='uncertain','Uncertain result lost');(new Publisher($app,$http))->run();check(count($http->calls)===1,'Uncertain POST repeated');});
test('stale in-flight publication is recovered as uncertain without HTTP',function()use($app,$fb){$id=scheduled($fb);$app->query("UPDATE publications SET status='processing',state_json=? WHERE post_id=?",[$app->seal(['in_flight'=>true]),$id]);$http=new FakeHttp();(new Publisher($app,$http))->run();check(publication($id)['status']==='uncertain','Stale request retried');check(!$http->calls,'Recovery used HTTP');});
$image=$app->root.'/storage/uploads/test.jpg';file_put_contents($image,'test');$app->query('INSERT INTO media(name,path,mime,bytes,width,height,public_key,created_at) VALUES(?,?,?,?,?,?,?,?)',['Test','test.jpg','image/jpeg',4,1080,1080,bin2hex(random_bytes(32)),$app->now()]);$imageId=(int)$app->db->lastInsertId();
$video=$app->root.'/storage/uploads/test.mp4';file_put_contents($video,'test-video');$app->query('INSERT INTO media(name,path,mime,bytes,public_key,created_at) VALUES(?,?,?,?,?,?)',['Video','test.mp4','video/mp4',10,bin2hex(random_bytes(32)),$app->now()]);$videoId=(int)$app->db->lastInsertId();
test('Facebook accepted video survives transient processing-status failure',function()use($app,$fb,$videoId){$id=scheduled($fb,[$videoId]);$http=new FakeHttp([['json'=>['id'=>'video-1']],new RemoteFailure('status temporarily unavailable',false,503)]);(new Publisher($app,$http))->run();$pub=publication($id);check($pub['status']==='pending','Polling failure discarded accepted video');check($app->unseal($pub['state_json'])['video_id']==='video-1','Video identity lost');$app->query('UPDATE publications SET next_at=? WHERE id=?',[$app->now(),$pub['id']]);$finish=new FakeHttp([['json'=>['status'=>['video_status'=>'ready']]]]);(new Publisher($app,$finish))->run();check(publication($id)['status']==='published','Polling did not resume');check(count($finish->calls)===1&&$finish->calls[0][0]==='GET','Video was uploaded again');});
test('Instagram checkpoints container and accepts success with caption warning',function()use($app,$imageId){$ig=channel('instagram',['access_token'=>'fake']);$id=scheduled($ig,[$imageId]);$http=new FakeHttp([['json'=>['id'=>'container-1']],['json'=>['status_code'=>'FINISHED']],['json'=>['id'=>'ig-post-1','config_issue'=>'CAPTION_NOT_ATTACHED']],['json'=>['permalink'=>'https://www.instagram.com/p/example/']]]);(new Publisher($app,$http))->run();$pub=publication($id);check($pub['status']==='published'&&str_contains($pub['last_error'],'CAPTION_NOT_ATTACHED'),'Partial-success warning lost');check(count($http->calls)===4,'Wrong Instagram sequence');});
test('YouTube refreshes once, sends resumable bytes and checks processing',function()use($app,$videoId){$yt=channel('youtube',['access_token'=>'expired','refresh_token'=>'refresh','expires_at'=>1]);$id=scheduled($yt,[$videoId]);$http=new FakeHttp([['json'=>['access_token'=>'fresh','expires_in'=>3600]],['headers'=>['location'=>'https://www.googleapis.com/upload/youtube/v3/videos?upload_id=test']],['status'=>308],function($method,$url,$headers,$body){check($method==='PUT'&&$body==='test-video','Wrong bytes sent');check(in_array('Content-Range: bytes 0-9/10',$headers,true),'Incorrect range');return ['status'=>201,'headers'=>[],'json'=>['id'=>'youtube-123']];},['json'=>['items'=>[['status'=>['uploadStatus'=>'processed']]]]]]);(new Publisher($app,$http))->run();check(publication($id)['status']==='published','YouTube did not complete');$refreshes=array_filter($http->calls,fn($call)=>str_contains($call[1],'oauth2.googleapis.com'));check(count($refreshes)===1,'Refreshed multiple times');});
test('started jobs cannot be edited; cancellation preserves publication history',function()use($app,$fb){$id=scheduled($fb);$app->query('UPDATE publications SET state_json=? WHERE post_id=?',[$app->seal(['container'=>'started']),$id]);rejects(fn()=>$app->savePost(['id'=>$id,'version'=>1,'title'=>'Edit','status'=>'draft']),'påbörjats');$app->cancelPost($id);check(publication($id)['status']==='cancelled','Not cancelled');check($app->one('SELECT id FROM posts WHERE id=?',[$id])!==null,'History deleted');});
test('YouTube resumes from server-confirmed byte position after lost transfer response',function()use($app,$videoId){$yt=channel('youtube',['access_token'=>'fresh','refresh_token'=>'refresh','expires_at'=>time()+3600]);$id=scheduled($yt,[$videoId]);$pub=publication($id);$app->query('UPDATE publications SET state_json=? WHERE id=?',[$app->seal(['upload_url'=>'https://www.googleapis.com/upload/youtube/v3/videos?upload_id=resume','offset'=>0,'query_upload'=>true]),$pub['id']]);$http=new FakeHttp([['status'=>308,'headers'=>['range'=>'bytes=0-4']],function($method,$url,$headers,$body){check($body==='video','Resent already-accepted bytes');check(in_array('Content-Range: bytes 5-9/10',$headers,true),'Resume range incorrect');return ['status'=>201,'headers'=>[],'json'=>['id'=>'resumed-123']];},['json'=>['items'=>[['status'=>['uploadStatus'=>'processed']]]]]]);(new Publisher($app,$http))->run();check(publication($id)['status']==='published','Resumed upload failed');});
test('mixed channel outcomes preserve each result independently',function()use($app){$a=channel('facebook',['access_token'=>'a']);$b=channel('facebook',['access_token'=>'b']);$id=scheduled($a);$app->query('INSERT INTO publications(post_id,channel_id,status,state_json,next_at,updated_at) VALUES(?,?,?,?,?,?)',[$id,$b,'pending','{}',$app->now(),$app->now()]);$http=new FakeHttp([new RemoteFailure('permission denied',false,403),['json'=>['id'=>'second-page-post']]]);(new Publisher($app,$http))->run();$pubs=$app->all('SELECT status FROM publications WHERE post_id=? ORDER BY id',[$id]);check(array_column($pubs,'status')===['failed','published'],'One channel overwrote another result');});
test('disconnect preserves identity/history and refuses new scheduling',function()use($app,$fb){$app->query('UPDATE channels SET active=0,credentials=? WHERE id=?',[$app->seal([]),$fb]);rejects(fn()=>scheduled($fb),'inte ansluten');check($app->one('SELECT external_id FROM channels WHERE id=?',[$fb])!==null,'History identity deleted');});
